// === ZENTRALE CONFIG ===
// Alle nachgelagerten Nodes lesen die Config ueber:
//   $('Config').first().json.cfg
const CONFIG = {
  // 'brutto' = Shop fuehrt Preise inkl. Steuer  |  'netto' = exkl. Steuer
  // Einmalig verifizieren:  { shop { taxesIncluded } }
  PREIS_MODUS: 'brutto',

  // JTL-Positionstypen (tBestellPos.nType), die ergaenzt werden duerfen
  // 0 = Artikel | 1 = Versand | 2 = Rabatt | 3 = Zuschlag | 4 = Gutschein | 9 = Text
  JTL_TYPEN_ERLAUBT: [0],

  // SKUs, die nie ergaenzt werden
  SKIP_SKUS: [],

  // Auftragsnummern pro SQL-Batch (IN-Liste)
  SQL_BATCH: 500,

  // Custom Items haben kein SKU-Feld -> SKU MUSS in den Titel,
  // sonst erkennt ein erneuter Lauf die Position nicht wieder.
  TITEL_SUFFIX: ' [SKU: {sku}]',
  SKU_REGEX: '\\[SKU:\\s*([^\\]]+)\\]',

  // Spalten-Mapping: erster nicht-leerer Treffer gewinnt
  COLS: {
    matrixify: {
      orderId:   ['ID', 'Order ID', 'Id'],
      orderName: ['Name', 'Order Name'],
      lineType:  ['Line: Type', 'Line Type'],
      sku:       ['Line: SKU', 'Line: Variant SKU', 'Line SKU'],
      titel:     ['Line: Title', 'Line: Name'],
      menge:     ['Line: Quantity', 'Line Quantity'],
      tags:      ['Tags'],
      currency:  ['Currency', 'Presentment Currency']
    }
  },
  MATRIXIFY_LINE_TYPE: 'line item'
};

// CSV-Binaries unveraendert durchreichen, Config an das erste Item haengen
const items = $input.all();
items[0].json = { ...items[0].json, cfg: CONFIG };
return items;

// Phase A: Matrixify -> Ist-Zustand in Shopify UND Nummernliste fuer die
// SQL-Abfrage. Kein API-Call, kein zweiter Upload.
const cfg = $('Config').first().json.cfg;
const sd = $getWorkflowStaticData('global');

// staticData ueberlebt Executions -> bei jedem Lauf hart zuruecksetzen
sd.shopify = {};
sd.jtl = {};
sd.report = [];

const pick = (row, cands) => {
  for (const c of cands) {
    const v = row[c];
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
  }
  return '';
};
const normSku = s => String(s || '').trim().toUpperCase();
const normName = s => {
  const t = String(s || '').trim();
  if (!t) return '';
  return t.startsWith('#') ? t : '#' + t;
};
const num = s => Number(String(s || '').replace(/\s/g, '').replace(',', '.')) || 0;

const rows = $('Matrixify parsen').all().map(i => i.json);
if (!rows.length) throw new Error('Matrixify-CSV ist leer oder wurde nicht geparst (Delimiter pruefen).');

const skuRe = new RegExp(cfg.SKU_REGEX, 'i');
const shopify = {};
const reihenfolge = [];

for (const row of rows) {
  const name = normName(pick(row, cfg.COLS.matrixify.orderName));
  if (!name) continue;
  if (!shopify[name]) {
    shopify[name] = { orderId: '', tags: '', currency: '', positionen: {} };
    reihenfolge.push(name);
  }
  const rec = shopify[name];

  const oid = pick(row, cfg.COLS.matrixify.orderId);
  if (oid) rec.orderId = oid.replace(/\D/g, '');
  const tg = pick(row, cfg.COLS.matrixify.tags);
  if (tg) rec.tags = tg;
  const cur = pick(row, cfg.COLS.matrixify.currency);
  if (cur) rec.currency = cur;

  // nur echte Line Items zaehlen (Shipping/Refund/Transaction-Zeilen ignorieren)
  const lt = pick(row, cfg.COLS.matrixify.lineType).toLowerCase();
  if (lt && lt !== cfg.MATRIXIFY_LINE_TYPE) continue;

  let sku = normSku(pick(row, cfg.COLS.matrixify.sku));
  if (!sku) {
    // bereits durch diesen Flow ergaenzte Custom Items: SKU steht im Titel
    const m = String(pick(row, cfg.COLS.matrixify.titel)).match(skuRe);
    if (m) sku = normSku(m[1]);
  }
  if (!sku) continue;

  const menge = num(pick(row, cfg.COLS.matrixify.menge));
  if (menge <= 0) continue;
  rec.positionen[sku] = (rec.positionen[sku] || 0) + menge;
}
sd.shopify = shopify;

if (!reihenfolge.length) {
  throw new Error('Keine Bestellnummern gefunden. Verfuegbare Spalten: ' + Object.keys(rows[0]).join(' | '));
}

// Nummernliste fuer SQL: ohne '#', da JTL die Nummer ohne Prefix speichert
const nummern = reihenfolge.map(n => n.replace(/^#/, ''));

const out = [];
for (let i = 0; i < nummern.length; i += cfg.SQL_BATCH) {
  out.push({ json: {
    chunk: Math.floor(i / cfg.SQL_BATCH) + 1,
    nummern: nummern.slice(i, i + cfg.SQL_BATCH),
    bestellungenGesamt: nummern.length
  }});
}
return out;

// Whitelist gegen SQL-Injection: nur unkritische Zeichen bleiben stehen.
const item = $input.first().json;
const safe = (item.nummern || [])
  .map(n => String(n).replace(/[^A-Za-z0-9#._\-\/]/g, ''))
  .filter(Boolean);
if (!safe.length) throw new Error('Leerer SQL-Batch (Chunk ' + item.chunk + ')');

return [{ json: {
  chunk: item.chunk,
  anzahl: safe.length,
  inList: safe.map(n => "'" + n + "'").join(',')
}}];

// Positionen filtern (Typ/SKU) und je Bestellung aggregieren.
const cfg = $('Config').first().json.cfg;
const sd = $getWorkflowStaticData('global');
if (!sd.jtl) sd.jtl = {};

const erlaubt = (cfg.JTL_TYPEN_ERLAUBT || []).map(Number);
const skipSkus = (cfg.SKIP_SKUS || []).map(s => String(s).toUpperCase());
const rows = $input.all().map(i => i.json).filter(r => r && r.jtlAuftragsNr !== undefined);

let uebernommen = 0, verworfen = 0;
for (const r of rows) {
  if (!erlaubt.includes(Number(r.posTyp))) { verworfen++; continue; }
  const sku = String(r.sku || '').trim().toUpperCase();
  if (!sku || skipSkus.includes(sku)) { verworfen++; continue; }

  const raw = String(r.shopBestellNr || '').trim() || String(r.jtlAuftragsNr || '').trim();
  const orderName = raw.startsWith('#') ? raw : '#' + raw;

  if (!sd.jtl[orderName]) {
    sd.jtl[orderName] = {
      jtlAuftragsNr: String(r.jtlAuftragsNr || '').trim(),
      waehrung: String(r.waehrung || '').trim(),
      bestelldatum: r.bestelldatum,
      positionen: {}
    };
  }
  const ziel = sd.jtl[orderName].positionen;
  const netto = Number(r.einzelNetto);
  const brutto = Number(r.einzelBrutto);

  if (!ziel[sku]) {
    ziel[sku] = {
      titel: String(r.titel || '').trim(),
      menge: 0,
      einzelNetto: netto,
      einzelBrutto: brutto,
      mwst: Number(r.mwstSatz),
      preisAbweichung: false
    };
  } else if (Math.abs(ziel[sku].einzelNetto - netto) > 0.005) {
    // gleiche SKU mehrfach mit unterschiedlichem Preis -> im Report markieren
    ziel[sku].preisAbweichung = true;
  }
  ziel[sku].menge += Number(r.menge) || 0;
  uebernommen++;
}

return [{ json: {
  chunk: $('IN-Liste bauen').first().json.chunk,
  zeilen: rows.length,
  uebernommen,
  verworfen,
  auftraegeGesamt: Object.keys(sd.jtl).length
}}];

// Soll (JTL) gegen Ist (Matrixify). Nur positive Deltas werden ergaenzt.
const cfg = $('Config').first().json.cfg;
const sd = $getWorkflowStaticData('global');
const jtl = sd.jtl || {};
const shop = sd.shopify || {};
if (!Array.isArray(sd.report)) sd.report = [];

const brutto = cfg.PREIS_MODUS === 'brutto';
const auftraege = [];

for (const [orderName, j] of Object.entries(jtl)) {
  const s = shop[orderName];

  if (!s) {
    sd.report.push({ status: 'NICHT_IN_MATRIXIFY', orderName, jtlAuftragsNr: j.jtlAuftragsNr,
      hinweis: 'Bestellung im Matrixify-Export nicht enthalten' });
    continue;
  }
  if (!s.orderId) {
    sd.report.push({ status: 'KEINE_ORDER_ID', orderName, jtlAuftragsNr: j.jtlAuftragsNr,
      hinweis: 'ID-Spalte im Matrixify-Export fehlt oder leer' });
    continue;
  }

  const fehlend = [];
  for (const [sku, p] of Object.entries(j.positionen)) {
    const ist = s.positionen[sku] || 0;
    const delta = Number(p.menge) - ist;
    if (delta <= 0) continue;

    const pos = {
      sku,
      titel: p.titel,
      menge: delta,
      mengeJtl: p.menge,
      mengeShopify: ist,
      einzelNetto: Number(p.einzelNetto).toFixed(2),
      einzelBrutto: Number(p.einzelBrutto).toFixed(2),
      mwst: p.mwst,
      preisAbweichung: !!p.preisAbweichung
    };
    fehlend.push(pos);
    sd.report.push({ status: 'GEPLANT', orderName, jtlAuftragsNr: j.jtlAuftragsNr,
      sku, titel: p.titel, menge: delta, mengeJtl: p.menge, mengeShopify: ist,
      preis: brutto ? pos.einzelBrutto : pos.einzelNetto,
      preisModus: cfg.PREIS_MODUS, mwst: p.mwst,
      waehrung: s.currency || j.waehrung,
      hinweis: p.preisAbweichung ? 'mehrere JTL-Preise fuer diese SKU - Preis der ersten Position verwendet' : '' });
  }

  // Ueberschuss: Shopify hat mehr als JTL -> Flow 1 loescht nicht, nur Report
  for (const [sku, ist] of Object.entries(s.positionen)) {
    const soll = j.positionen[sku] ? Number(j.positionen[sku].menge) : 0;
    if (ist > soll) {
      sd.report.push({ status: 'UEBERSCHUSS_IN_SHOPIFY', orderName, jtlAuftragsNr: j.jtlAuftragsNr,
        sku, mengeJtl: soll, mengeShopify: ist, hinweis: 'manuell pruefen - wird nicht automatisch entfernt' });
    }
  }

  if (fehlend.length) {
    auftraege.push({
      orderName,
      orderGid: 'gid://shopify/Order/' + s.orderId,
      jtlAuftragsNr: j.jtlAuftragsNr,
      waehrung: s.currency || j.waehrung || 'EUR',
      tags: s.tags,
      positionen: fehlend
    });
  }
}

// Bestellung liegt in Shopify, aber SQL hat dazu nichts geliefert
// -> Mapping-Problem (cInetBestellNr) oder Auftrag nicht in JTL
for (const orderName of Object.keys(shop)) {
  if (!jtl[orderName]) {
    sd.report.push({ status: 'NICHT_IN_JTL', orderName,
      hinweis: 'kein JTL-Auftrag zu dieser Nummer gefunden - Mapping cInetBestellNr pruefen' });
  }
}

if (!auftraege.length) {
  return [{ json: { HINWEIS: 'Keine fehlenden Positionen gefunden', reportZeilen: sd.report.length } }];
}
return auftraege.map(a => ({ json: a }));

// Gate fuer kontrollierte Erstlaeufe. Limit = 0 -> alle Bestellungen.
const limit = Number($('CSV hochladen (Formular)').first().json['Limit']) || 0;
const items = $input.all();
const echte = items.filter(i => i.json.HINWEIS === undefined);
if (!echte.length) return items;
return limit > 0 ? echte.slice(0, limit) : echte;

const item = $input.item.json;
const body = {
  query: `mutation orderEditBegin($id: ID!) { orderEditBegin(id: $id) { calculatedOrder { id } userErrors { field message } } }`,
  variables: { id: item.orderGid }
};
return { json: {
  ...item,
  accessToken: $('Token holen').first().json.access_token,
  gqlBody: JSON.stringify(body)
}};

const resp = $input.first().json;
if (resp.errors) throw new Error('orderEditBegin GraphQL errors: ' + JSON.stringify(resp.errors));
const begin = resp?.data?.orderEditBegin;
const errs = begin?.userErrors || [];
if (errs.length) throw new Error('orderEditBegin userErrors: ' + JSON.stringify(errs));
const calcOrderId = begin?.calculatedOrder?.id;
if (!calcOrderId) throw new Error('Keine calculatedOrder.id erhalten: ' + JSON.stringify(resp));

const src = $('Query bauen (orderEditBegin)').first().json;
return { json: { ...src, calcOrderId } };

// Ein GraphQL-Dokument mit einem aliasierten orderEditAddCustomItem pro
// fehlender Position -> ein Edit-Zyklus je Bestellung.
// Custom Item statt AddVariant, weil AddVariant zwingend den AKTUELLEN
// Variantenpreis zieht. Preis kommt aus tBestellPos (historisch korrekt).
const cfg = $('Config').first().json.cfg;
const src = $input.first().json;
const brutto = cfg.PREIS_MODUS === 'brutto';
const cur = src.waehrung || 'EUR';
const pos = src.positionen || [];
if (!pos.length) throw new Error('Keine Positionen fuer ' + src.orderName);

const defs = [];
const parts = [];
const vars = { id: src.calcOrderId };

pos.forEach((p, i) => {
  vars['title' + i] = String(p.titel) + String(cfg.TITEL_SUFFIX).replace('{sku}', p.sku);
  vars['price' + i] = { amount: String(brutto ? p.einzelBrutto : p.einzelNetto), currencyCode: cur };
  vars['qty' + i] = Number(p.menge);
  defs.push('$title' + i + ': String!, $price' + i + ': MoneyInput!, $qty' + i + ': Int!');
  parts.push(
    'p' + i + ': orderEditAddCustomItem(id: $id, title: $title' + i + ', price: $price' + i +
    ', quantity: $qty' + i + ', taxable: true, requiresShipping: false) ' +
    '{ calculatedLineItem { id title quantity } userErrors { field message } }'
  );
});

const query = 'mutation addCustomItems($id: ID!, ' + defs.join(', ') + ') {\n  ' + parts.join('\n  ') + '\n}';

return { json: { ...src, positionenAnzahl: pos.length, gqlBody: JSON.stringify({ query, variables: vars }) } };

const resp = $input.first().json;
const src = $('Query bauen (Custom Items)').first().json;
if (resp.errors) throw new Error('addCustomItem GraphQL errors (' + src.orderName + '): ' + JSON.stringify(resp.errors));

const data = resp?.data || {};
const errs = [];
let added = 0;
for (const [alias, val] of Object.entries(data)) {
  if (val?.userErrors?.length) errs.push({ alias, userErrors: val.userErrors });
  if (val?.calculatedLineItem?.id) added++;
}
// Abbruch VOR dem Commit -> unvollstaendige Edits werden nicht uebernommen
if (errs.length) throw new Error('addCustomItem userErrors (' + src.orderName + '): ' + JSON.stringify(errs));
if (added !== src.positionenAnzahl) {
  throw new Error('Nur ' + added + ' von ' + src.positionenAnzahl + ' Positionen angelegt (' + src.orderName + ')');
}
return { json: { ...src, hinzugefuegt: added } };

const resp = $input.first().json;
const src = $('Add-Ergebnis pruefen').first().json;
if (resp.errors) throw new Error('orderEditCommit GraphQL errors (' + src.orderName + '): ' + JSON.stringify(resp.errors));
const c = resp?.data?.orderEditCommit;
if (c?.userErrors?.length) throw new Error('orderEditCommit userErrors (' + src.orderName + '): ' + JSON.stringify(c.userErrors));
const order = c?.order;
if (!order?.id) throw new Error('Kein Order-Objekt nach Commit (' + src.orderName + '): ' + JSON.stringify(resp));

return { json: {
  ...src,
  committedOrderId: order.id,
  orderNameShopify: order.name,
  statusVorPaid: order.displayFinancialStatus
}};

// Kein Abbruch: ein fehlgeschlagenes MarkAsPaid darf den Batch nicht stoppen.
const resp = $input.first().json;
const src = $('Commit-Ergebnis pruefen').first().json;
const p = resp?.data?.orderMarkAsPaid;
const errs = (p?.userErrors && p.userErrors.length ? p.userErrors : null) || resp?.errors || null;

return { json: {
  ...src,
  paidStatus: p?.order?.displayFinancialStatus || 'FEHLER',
  paidFehler: errs ? JSON.stringify(errs) : ''
}};

const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.report)) sd.report = [];
const cfg = $('Config').first().json.cfg;
const src = $('Paid-Ergebnis pruefen').first().json;
const brutto = cfg.PREIS_MODUS === 'brutto';

for (const p of src.positionen) {
  sd.report.push({
    status: 'ERGAENZT',
    orderName: src.orderName,
    jtlAuftragsNr: src.jtlAuftragsNr,
    sku: p.sku,
    titel: p.titel,
    menge: p.menge,
    mengeJtl: p.mengeJtl,
    mengeShopify: p.mengeShopify,
    preis: brutto ? p.einzelBrutto : p.einzelNetto,
    preisModus: cfg.PREIS_MODUS,
    mwst: p.mwst,
    waehrung: src.waehrung,
    paidStatus: src.paidStatus,
    hinweis: [src.paidFehler, p.preisAbweichung ? 'mehrere JTL-Preise fuer diese SKU' : ''].filter(Boolean).join(' | ')
  });
}

return [{ json: {
  orderName: src.orderName,
  positionen: src.positionen.length,
  paidStatus: src.paidStatus,
  paidFehler: src.paidFehler
}}];

const sd = $getWorkflowStaticData('global');
const form = $('CSV hochladen (Formular)').first().json;
const modus = form['Dry-Run'] === 'ja' ? 'DRY-RUN' : 'LIVE';
const monat = form['Monat'];
const rows = sd.report || [];

if (!rows.length) {
  return [{ json: { monat, modus, status: 'KEINE_ABWEICHUNGEN', hinweis: 'JTL und Shopify sind deckungsgleich' } }];
}
return rows.map(r => ({ json: { monat, modus, ...r } }));
